use serde_json::{Value, from_str};

pub fn solve(input: Value) -> Value {
    let jobs: Vec<i64> = input["jobs"].as_array().unwrap().iter().map(|v| v.as_i64().unwrap()).collect();
    let quantum: i64 = input["quantum"].as_i64().unwrap();

    let mut remaining_work: Vec<(usize, i64)> = (0..jobs.len()).map(|i| (i, jobs[i])).collect();
    remaining_work.sort_by_key(|&(_, work)| work);

    let mut result: Vec<usize> = Vec::new();
    while !remaining_work.is_empty() {
        let mut turn_work: Vec<(usize, i64)> = Vec::new();
        for (index, work) in remaining_work.iter().take(quantum as usize).map(|&(i, w)| (i, w)) {
            if work > 0 {
                turn_work.push((index, work - 1));
            }
        }
        result.extend(turn_work.iter().map(|&(i, _)| i));
        remaining_work = turn_work.into_iter().chain(remaining_work.into_iter().skip(quantum as usize)).collect();
    }

    Value::Array(result.into_iter().map(|i| Value::Number(i.into())).collect())
}
